    hero.append(node('p',adjusting?'HUMAN ADJUSTMENT':'SUGGESTED FIX','eyebrow'),node('h2',adjusting?'Make a small adjustment.':'A balance change needs attention.','panel-title'));
    if(instrument)hero.append(node('p',instrument.family,'section-title'),node('strong',actionable?balanceText(instrument):'Balance unavailable','live-figure'),node('p','Relative to the uploaded reference','muted'),node('p',conciseConfidence(instrument.confidence),'muted'));
