async function sendCommand(action,payload){if(viewMode!=='authoritative'||pendingCommand)return null;const guard=commandGuard(action,viewMode,runtimeAdapter,snapshot,runtimeConnected,receiptMs,Date.now(),resultDeadlines.deadline(snapshot));if(!guard.allowed){statusMessage(productError(guard.reason));return null;}const c=commandFor(snapshot,action,payload,`ui-${action}-${crypto.randomUUID()}`);const verificationBefore=snapshot.latest_verification?.verification_id??'none';operationStatus=null;technicalDetail=null;pendingCommand=true;renderConsole();try{const response=await runtimeAdapter.command(c);if(action==='recheck')verificationRequestedFor=`${c.session_id}:${payload.adjustment_id}:${verificationBefore}`;return response;}catch(e){showError(e);return null;}finally{pendingCommand=false;if(page==='console')renderConsole();}}
